    (function waitLeaflet() {
        if (typeof window._leaflet_map === 'undefined') {
            var maps = [];
            for (var k in window) {
                if (window[k] && window[k]._leaflet_id) maps.push(window[k]);
            }
            if (maps.length === 0) { setTimeout(waitLeaflet, 300); return; }
            var map = maps[maps.length-1];
            map.fitBounds([[43.2810039,-5.9422535],[43.328216799999986,-5.829154300000001]]);
        }
        var ctrl = document.querySelector('.leaflet-control-layers');
        if (ctrl) ctrl.classList.remove('leaflet-control-layers-expanded');
        setTimeout(function() {
            var ctrl2 = document.querySelector('.leaflet-control-layers');
            if (ctrl2) ctrl2.classList.remove('leaflet-control-layers-expanded');
        }, 1000);
    })();
    

