function terraAdjuntarNotas(mapaTerraNotas) {
    if (!mapaTerraNotas || mapaTerraNotas._terraNotasAdjuntadas) { return; }
    mapaTerraNotas._terraNotasAdjuntadas = true;
    var notaModoActivo = false;

    var ControlNotasTerra = L.Control.extend({
        options: {position: 'topleft'},
        onAdd: function(map) {
            var div = L.DomUtil.create('div', 'leaflet-bar terra-notas-control');
            div.innerHTML = '<a href="#" title="Anadir nota de campo">\ud83d\udccc</a>';
            L.DomEvent.disableClickPropagation(div);
            L.DomEvent.on(div, 'click', function(e) {
                L.DomEvent.preventDefault(e);
                notaModoActivo = !notaModoActivo;
                div.classList.toggle('terra-notas-activo', notaModoActivo);
                mapaTerraNotas.getContainer().style.cursor = notaModoActivo ? 'crosshair' : '';
            });
            return div;
        }
    });
    mapaTerraNotas.addControl(new ControlNotasTerra());

    function escaparHtmlNota(s) {
        return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    }

    function crearPopupNota(marker, textoInicial) {
        var texto = textoInicial;
        var html = '<div class="terra-nota-popup">' +
            '<div class="terra-nota-texto">' + escaparHtmlNota(texto).replace(/\n/g, '<br>') + '</div>' +
            '<div class="terra-nota-acciones">' +
            '<a class="terra-nota-editar">Editar</a> &middot; ' +
            '<a class="terra-nota-borrar">Borrar</a>' +
            '</div></div>';
        marker.bindPopup(html);
        marker.on('popupopen', function() {
            var popupEl = marker.getPopup().getElement();
            if (!popupEl) { return; }
            var btnEditar = popupEl.querySelector('.terra-nota-editar');
            var btnBorrar = popupEl.querySelector('.terra-nota-borrar');
            if (btnEditar) {
                btnEditar.onclick = function(ev) {
                    ev.preventDefault();
                    var nuevo = window.prompt('Editar nota de campo:', texto);
                    if (nuevo !== null && nuevo.trim() !== '') {
                        texto = nuevo.trim();
                        crearPopupNota(marker, texto);
                        marker.openPopup();
                    }
                };
            }
            if (btnBorrar) {
                btnBorrar.onclick = function(ev) {
                    ev.preventDefault();
                    mapaTerraNotas.removeLayer(marker);
                };
            }
        });
    }

    var iconoChinchetaTerra = L.divIcon({
        className: 'terra-nota-icono',
        html: '<div style="font-size:24px;line-height:24px;">\ud83d\udccc</div>',
        iconSize: [24, 24],
        iconAnchor: [12, 24],
        popupAnchor: [0, -22]
    });

    mapaTerraNotas.on('click', function(e) {
        if (!notaModoActivo) { return; }
        var texto = window.prompt("Nota de campo (ej. 'fuente sin catalogar'):", '');
        if (texto === null || texto.trim() === '') { return; }
        var marker = L.marker(e.latlng, {icon: iconoChinchetaTerra, draggable: true}).addTo(mapaTerraNotas);
        crearPopupNota(marker, texto.trim());
        marker.openPopup();
    });
}

function terraInicializarNotas() {
    Object.keys(window).forEach(function(k) {
        if (k.indexOf('map_') === 0 && window[k] instanceof L.Map) {
            terraAdjuntarNotas(window[k]);
        }
    });
}
