function terraAdjuntarDiagnostico(mapaTerraDiag) {
    if (!mapaTerraDiag || mapaTerraDiag._terraDiagAdjuntado) { return; }
    mapaTerraDiag._terraDiagAdjuntado = true;
    var diagModoActivo = false;

    var ControlDiagTerra = L.Control.extend({
        options: {position: 'topleft'},
        onAdd: function(map) {
            var div = L.DomUtil.create('div', 'leaflet-bar terra-diag-control');
            div.innerHTML = '<a href="#" title="Diagnostico rapido de este punto">\ud83d\udd0d</a>';
            L.DomEvent.disableClickPropagation(div);
            L.DomEvent.on(div, 'click', function(e) {
                L.DomEvent.preventDefault(e);
                diagModoActivo = !diagModoActivo;
                div.classList.toggle('terra-diag-activo', diagModoActivo);
                mapaTerraDiag.getContainer().style.cursor = diagModoActivo ? 'help' : '';
            });
            return div;
        }
    });
    mapaTerraDiag.addControl(new ControlDiagTerra());

    function puntoEnAnillo(punto, anillo) {
        var dentro = false;
        for (var i = 0, j = anillo.length - 1; i < anillo.length; j = i++) {
            var xi = anillo[i][0], yi = anillo[i][1];
            var xj = anillo[j][0], yj = anillo[j][1];
            var interseca = ((yi > punto[1]) !== (yj > punto[1])) &&
                (punto[0] < (xj - xi) * (punto[1] - yi) / (yj - yi) + xi);
            if (interseca) { dentro = !dentro; }
        }
        return dentro;
    }

    function puntoEnPoligono(lng, lat, geometry) {
        var punto = [lng, lat];
        if (geometry.type === 'Polygon') {
            if (!puntoEnAnillo(punto, geometry.coordinates[0])) { return false; }
            for (var h = 1; h < geometry.coordinates.length; h++) {
                if (puntoEnAnillo(punto, geometry.coordinates[h])) { return false; }
            }
            return true;
        }
        if (geometry.type === 'MultiPolygon') {
            for (var p = 0; p < geometry.coordinates.length; p++) {
                var anillos = geometry.coordinates[p];
                if (puntoEnAnillo(punto, anillos[0])) {
                    var enHueco = false;
                    for (var h2 = 1; h2 < anillos.length; h2++) {
                        if (puntoEnAnillo(punto, anillos[h2])) { enHueco = true; break; }
                    }
                    if (!enHueco) { return true; }
                }
            }
            return false;
        }
        return false;
    }

    function buscarEnCapa(overlays, nombreParcial, lat, lng, callback) {
        for (var nombreCompleto in overlays) {
            if (nombreCompleto.indexOf(nombreParcial) === -1) { continue; }
            var capa = overlays[nombreCompleto];
            if (!capa || !capa.eachLayer) { continue; }
            capa.eachLayer(function(subcapa) {
                if (!subcapa.feature || !subcapa.feature.geometry) { return; }
                if (puntoEnPoligono(lng, lat, subcapa.feature.geometry)) {
                    callback(nombreCompleto, subcapa.feature.properties || {});
                }
            });
        }
    }

    function localizarOverlays() {
        for (var k in window) {
            if (k.indexOf('layer_control_') === 0 && k.indexOf('_layers') === (k.length - 7)) {
                if (window[k] && window[k].overlays) { return window[k].overlays; }
            }
        }
        return null;
    }

    mapaTerraDiag.on('click', function(e) {
        if (!diagModoActivo) { return; }
        var overlays = localizarOverlays();
        var resultados = [];
        if (overlays) {
            buscarEnCapa(overlays, 'Uso del Suelo', e.latlng.lat, e.latlng.lng, function(nombre, props) {
                var etiqueta = props.hilucs_label || 'Uso del suelo (sin etiqueta)';
                resultados.push('<div class="terra-diag-item"><b>Uso del suelo:</b> ' + etiqueta + '</div>');
            });
            buscarEnCapa(overlays, 'Red Natura 2000', e.latlng.lat, e.latlng.lng, function(nombre, props) {
                var etiqueta = (props.SITE_NAME || 'Espacio Red Natura') + (props.TIPO ? ' (' + props.TIPO + ')' : '');
                resultados.push('<div class="terra-diag-item"><b>\ud83e\udd8b Red Natura 2000:</b> ' + etiqueta + '</div>');
            });
            buscarEnCapa(overlays, 'Espacios Naturales Protegidos', e.latlng.lat, e.latlng.lng, function(nombre, props) {
                var etiqueta = (props.nombre || 'Espacio protegido') + (props.figura ? ' (' + props.figura + ')' : '');
                resultados.push('<div class="terra-diag-item"><b>\ud83c\udfde\ufe0f Espacio protegido:</b> ' + etiqueta + '</div>');
            });
        }
        var cuerpo = resultados.length > 0
            ? resultados.join('')
            : '<div class="terra-diag-vacio">Sin coincidencias en las capas cargadas para este punto (activa las capas de Uso del Suelo / Red Natura / ENP en el panel de capas si estan ocultas).</div>';
        var html = '<div class="terra-diag-popup"><h4>\ud83d\udd0d Diagnostico rapido</h4>' + cuerpo + '</div>';
        L.popup({maxWidth: 280}).setLatLng(e.latlng).setContent(html).openOn(mapaTerraDiag);
    });
}

