function terraAdjuntarComparador(mapaTerraComp) {
    if (!mapaTerraComp || mapaTerraComp._terraCompAdjuntado) { return; }
    mapaTerraComp._terraCompAdjuntado = true;
    var compModoActivo = false;
    var capaT1 = null, capaT2 = null, capaCambio = null;
    var etiquetaT1 = "T1", etiquetaT2 = "T2";

    function localizarOverlays() {
        for (var k in window) {
            if (k.indexOf('layer_control_') === 0 && k.indexOf('_layers') === (k.length - 7)) {
                if (window[k] && window[k].overlays) { return window[k].overlays; }
            }
        }
        return null;
    }

    function localizarCapasNDVI() {
        var overlays = localizarOverlays();
        if (!overlays) { return; }
        for (var nombre in overlays) {
            if (nombre.indexOf('NDVI ') === -1) { continue; }
            if (nombre.indexOf('Cambio NDVI') !== -1) {
                capaCambio = overlays[nombre];
                continue;
            }
            if (nombre.indexOf('\ud83d\udfe1') !== -1) {
                capaT1 = overlays[nombre];
                etiquetaT1 = nombre.split(' ').pop();
            } else if (nombre.indexOf('\ud83d\udfe2') !== -1) {
                capaT2 = overlays[nombre];
                etiquetaT2 = nombre.split(' ').pop();
            }
        }
    }

    var panel = L.DomUtil.create('div', 'terra-comp-panel');
    panel.innerHTML =
        '<span>' + '</span>' +
        '<input type="range" min="0" max="100" value="50" class="terra-comp-slider">' +
        '<span class="terra-comp-etiquetas"></span>';
    mapaTerraComp.getContainer().appendChild(panel);
    var slider = panel.querySelector('.terra-comp-slider');
    var etiquetasSpan = panel.querySelector('.terra-comp-etiquetas');

    var linea = L.DomUtil.create('div', 'terra-comp-linea');
    mapaTerraComp.getContainer().appendChild(linea);

    L.DomEvent.disableClickPropagation(panel);
    L.DomEvent.disableScrollPropagation(panel);

    var ultimoPct = 50;

    function aplicarPosicion(pct) {
        ultimoPct = pct;
        var contenedor = mapaTerraComp.getContainer();
        var rectContenedor = contenedor.getBoundingClientRect();
        var anchoContenedor = rectContenedor.width;
        var xLineaAbsoluta = rectContenedor.left + (anchoContenedor * pct / 100);
        linea.style.left = (anchoContenedor * pct / 100) + 'px';

        if (capaT2) {
            var imgT2 = capaT2.getElement();
            if (imgT2) {
                var rectImg = imgT2.getBoundingClientRect();
                var pctRelativoImg = 0;
                if (rectImg.width > 0) {
                    pctRelativoImg = ((xLineaAbsoluta - rectImg.left) / rectImg.width) * 100;
                    pctRelativoImg = Math.max(0, Math.min(100, pctRelativoImg));
                }
                imgT2.style.clipPath = 'inset(0 0 0 ' + pctRelativoImg + '%)';
                imgT2.style.zIndex = 650;
            }
        }
        if (capaT1) {
            var imgT1 = capaT1.getElement();
            if (imgT1) {
                imgT1.style.clipPath = 'none';
                imgT1.style.zIndex = 640;
            }
        }
    }

    mapaTerraComp.on('move zoom', function() {
        if (compModoActivo) { aplicarPosicion(ultimoPct); }
    });

    slider.addEventListener('input', function() {
        aplicarPosicion(parseInt(slider.value, 10));
    });

    var ControlCompTerra = L.Control.extend({
        options: {position: 'topleft'},
        onAdd: function(map) {
            var div = L.DomUtil.create('div', 'leaflet-bar terra-comp-control');
            div.innerHTML = '<a href="#" title="Comparador temporal NDVI">\u2194\ufe0f</a>';
            L.DomEvent.disableClickPropagation(div);
            L.DomEvent.on(div, 'click', function(e) {
                L.DomEvent.preventDefault(e);
                if (!capaT1 || !capaT2) { localizarCapasNDVI(); }
                if (!capaT1 || !capaT2) {
                    window.alert('No se encontraron las capas NDVI de ambas fechas en este visor.');
                    return;
                }
                compModoActivo = !compModoActivo;
                div.classList.toggle('terra-comp-activo', compModoActivo);
                panel.classList.toggle('terra-comp-visible', compModoActivo);
                linea.classList.toggle('terra-comp-visible', compModoActivo);
                if (compModoActivo) {
                    if (!mapaTerraComp.hasLayer(capaT1)) { mapaTerraComp.addLayer(capaT1); }
                    if (!mapaTerraComp.hasLayer(capaT2)) { mapaTerraComp.addLayer(capaT2); }
                    if (capaCambio && mapaTerraComp.hasLayer(capaCambio)) {
                        mapaTerraComp.removeLayer(capaCambio);
                    }
                    etiquetasSpan.textContent = etiquetaT1 + '  \u2194  ' + etiquetaT2;
                    aplicarPosicion(parseInt(slider.value, 10));
                }
            });
            return div;
        }
    });
    mapaTerraComp.addControl(new ControlCompTerra());
}

function terraInicializarComparador() {
    Object.keys(window).forEach(function(k) {
        if (k.indexOf('map_') === 0 && window[k] instanceof L.Map) {
            terraAdjuntarComparador(window[k]);
        }
    });
}
if (document.readyState === 'complete') {
    terraInicializarComparador();
} else {
    window.addEventListener('load', terraInicializarComparador);
}


