    function(layer){
    let div = L.DomUtil.create('div');
    
    let handleObject = feature => {
        if (feature === null) {
            return '';
        } else if (typeof(feature)=='object') {
            return JSON.stringify(feature);
        } else {
            return feature;
        }
    }
    let fields = ["Tipo_de_Suelo_Urbanizable", "Nombre", "\u00c1rea_(m.2)", "Uso_Predominante", "Edificabilidad_(m.2/m.2)", "Aprovechamiento_Medio"];
    let aliases = ["Tipo_de_Suelo_Urbanizable", "Nombre", "\u00c1rea_(m.2)", "Uso_Predominante", "Edificabilidad_(m.2/m.2)", "Aprovechamiento_Medio"];
    let table = '<table>' +
        String(
        fields.map(
        (v,i)=>
        `<tr>
            <th>${aliases[i]}</th>
            
            <td>${handleObject(layer.feature.properties[v])}</td>
        </tr>`).join(''))
    +'</table>';
    div.innerHTML=table;
    
    return div
    }
